import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

export type UserStatus = 'active' | 'disabled';

export interface User {
  id: string;
  name: string;
  role: string;
  status: UserStatus;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_TOKEN: Record<UserStatus, string> = {
  active: 'var(--jx-color-success)',
  disabled: 'var(--jx-color-danger)',
};

function StatusBadge({ status }: { status: UserStatus }) {
  return (
    <span
      className="jx-badge"
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 'var(--jx-space-1)',
        padding: 'var(--jx-space-1) var(--jx-space-2)',
        borderRadius: 'var(--jx-radius-full)',
        border: '1px solid currentColor',
        color: STATUS_TOKEN[status],
        fontSize: 'var(--jx-font-size-sm)',
        lineHeight: 1.2,
        whiteSpace: 'nowrap',
      }}
    >
      <span
        aria-hidden="true"
        style={{
          width: 'var(--jx-space-2)',
          height: 'var(--jx-space-2)',
          borderRadius: 'var(--jx-radius-full)',
          background: 'currentColor',
        }}
      />
      {STATUS_LABEL[status]}
    </span>
  );
}

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE),
    [users, safePage],
  );

  const cellStyle = {
    padding: 'var(--jx-space-3)',
    borderBottom: '1px solid var(--jx-color-border)',
    textAlign: 'left' as const,
  };

  return (
    <div
      className="jx-stack"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}
    >
      <table
        className="jx-table"
        style={{
          width: '100%',
          borderCollapse: 'collapse',
          background: 'var(--jx-color-surface)',
          color: 'var(--jx-color-text)',
        }}
      >
        <thead>
          <tr>
            <th scope="col" style={{ ...cellStyle, color: 'var(--jx-color-text-muted)' }}>
              Имя
            </th>
            <th scope="col" style={{ ...cellStyle, color: 'var(--jx-color-text-muted)' }}>
              Роль
            </th>
            <th scope="col" style={{ ...cellStyle, color: 'var(--jx-color-text-muted)' }}>
              Статус
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.length === 0 ? (
            <tr>
              <td colSpan={3} style={{ ...cellStyle, color: 'var(--jx-color-text-muted)' }}>
                Пользователей нет
              </td>
            </tr>
          ) : (
            rows.map((user) => (
              <tr key={user.id}>
                <td style={cellStyle}>{user.name}</td>
                <td style={cellStyle}>{user.role}</td>
                <td style={cellStyle}>
                  <StatusBadge status={user.status} />
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      <nav
        aria-label="Навигация по страницам"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <JxButton
          variant="secondary"
          disabled={safePage <= 1}
          onClick={() => setPage(safePage - 1)}
        >
          Назад
        </JxButton>

        <span
          aria-live="polite"
          style={{ color: 'var(--jx-color-text-muted)', fontSize: 'var(--jx-font-size-sm)' }}
        >
          Страница {safePage} из {pageCount}
        </span>

        <JxButton
          variant="secondary"
          disabled={safePage >= pageCount}
          onClick={() => setPage(safePage + 1)}
        >
          Вперёд
        </JxButton>
      </nav>
    </div>
  );
}

